    },
    [4] = {
      beijing = 4735,
      dialog = 3,
      music = "48_Quiet_Daily",
      renwu = "npc",
      sentence = "Fortunately, last night Lucien only dropped me off near my residence. If he had insisted on seeing me all the way to my doorstep, then I suppose I would have been found out immediately.",
      next = {5}
    },
    [5] = {
      beijing = 4735,
      dialog = 3,
      music = "48_Quiet_Daily",
      renwu = "npc",
      sentence = "—But for a sly fox like him, perhaps he'd already figured it out long ago?",
