    },
    [8] = {
      beijing = 4735,
      dialog = 3,
      music = "48_Quiet_Daily",
      renwu = "npc",
      sentence = "I had been thinking about this jumble of thoughts from before I went to bed till waking up, and I still hadn't reached a conclusion.",
